import type { EngineInterface, Register } from 'claude-code'

import { contextPercent, formatMeter, warnStep } from './format'
import type { MeterOptions } from './format'

type Meter = MeterOptions & {
  warnAtPercent: number
  /**
   * Whether the warning toast has fired since the context was last below the
   * threshold. A hot reload resets it, which at worst repeats one toast.
   */
  warned: boolean
}

/** Reads the session's usage and redraws the status line; toasts once at the threshold. */
async function refresh($: EngineInterface, meter: Meter): Promise<void> {
  // No `breakdown`: the status-line figures alone, which cost no request.
  const usage = await $.session.usage()
  $.ui.status(formatMeter(usage, meter))
  const percent = contextPercent(usage)
  const step = warnStep(percent, meter.warnAtPercent, meter.warned)
  meter.warned = step.warned
  if (step.toast) {
    $.ui.toast(`Context is ${percent}% full. Consider /compact or /clear soon.`)
  }
}

export const register: Register = (on, options) => {
  const meter: Meter = {
    showCost: options.showCost !== false,
    showRateLimits: options.showRateLimits !== false,
    format: options.format === 'verbose' ? 'verbose' : 'compact',
    warnAtPercent: typeof options.warnAtPercent === 'number' ? options.warnAtPercent : 80,
    warned: false,
  }
  const intervalMs = Math.max(5_000, typeof options.intervalMs === 'number' ? options.intervalMs : 60_000)

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await refresh($, meter)
    $.clock.every(intervalMs, () => {
      refresh($, meter).catch(() => undefined)
    })
    return started
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined) await refresh($, meter)
    return result
  })

  // Never gates the compaction: it refreshes after `next` and, should that
  // throw, the catch replays what `next` settled to.
  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    await refresh($, meter)
    return result
  }).catch(($, e, next) => next(e))
}

