/**
 * Pure helpers for cm-context-meter: no `$`, so they are unit-tested directly.
 */
import type { SessionUsage } from 'claude-code'

export type MeterOptions = {
  showCost: boolean
  showRateLimits: boolean
  format: 'compact' | 'verbose'
}

/** The context window's fill as a whole percentage, or undefined before any response. */
export function contextPercent(usage: SessionUsage): number | undefined {
  const { percent, tokens, window } = usage.context
  if (typeof percent === 'number') return Math.round(percent)
  if (typeof tokens === 'number' && window > 0) return Math.round((tokens / window) * 100)
  return undefined
}

/** `84k`, `1.2M`, `950`: a token count, short. */
export function shortTokens(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`
  if (n >= 1_000) return `${Math.round(n / 1_000)}k`
  return String(n)
}

const LIMIT_LABELS: Record<string, { compact: string; verbose: string }> = {
  five_hour: { compact: '5h', verbose: '5-hour' },
  seven_day: { compact: '7d', verbose: '7-day' },
  spend_limit: { compact: 'spend', verbose: 'Spend limit' },
}

function pct(n: number): string {
  return `${Number.isInteger(n) ? n : n.toFixed(1)}%`
}

/**
 * The status line: `ctx 42% · 5h 23% · 7d 61% · $1.20` (compact) or
 * `Context 42% (84k/200k) · 5-hour 23% · 7-day 61% · Cost $1.20` (verbose).
 * Figures the engine does not have are left out, never zeroed.
 */
export function formatMeter(usage: SessionUsage, options: MeterOptions): string {
  const verbose = options.format === 'verbose'
  const parts: string[] = []
  const ctx = contextPercent(usage)
  const ctxText = ctx === undefined ? '–' : `${ctx}%`
  if (verbose) {
    const tokens = usage.context.tokens
    const detail = typeof tokens === 'number' ? ` (${shortTokens(tokens)}/${shortTokens(usage.context.window)})` : ''
    parts.push(`Context ${ctxText}${detail}`)
  } else {
    parts.push(`ctx ${ctxText}`)
  }
  if (options.showRateLimits) {
    for (const limit of usage.rateLimits) {
      const label = LIMIT_LABELS[limit.kind]?.[verbose ? 'verbose' : 'compact'] ?? limit.kind
      parts.push(`${label} ${pct(limit.percentUsed)}`)
    }
  }
  if (options.showCost && usage.cost !== undefined) {
    parts.push(`${verbose ? 'Cost ' : ''}$${usage.cost.usd.toFixed(2)}`)
  }
  return parts.join(' · ')
}

/**
 * Whether to toast now: the context just reached `warnAt` and no toast has
 * been shown since it was last below it. Returns the new "warned" flag too.
 */
export function warnStep(percent: number | undefined, warnAt: number, wasWarned: boolean): { toast: boolean; warned: boolean } {
  if (percent === undefined || warnAt <= 0) return { toast: false, warned: wasWarned }
  if (percent >= warnAt) return { toast: !wasWarned, warned: true }
  return { toast: false, warned: false }
}

